<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { NASA_SOURCE, PLANETS } from '../features/solar-system/planets'
import { createSolarScene } from '../features/solar-system/scene'
import { MISSIONS, filterMissions } from '../features/solar-system/missions'
import { sceneTime } from '../features/solar-system/surface'
import { useExpandedScene } from '../utils/useExpandedScene'
const { expanded, toggle: toggleScene } = useExpandedScene(() => stop())
const route = useRoute(), router = useRouter(), mount = ref(null), selectedId = ref(PLANETS.some(p => p.id === route.query.planet) ? route.query.planet : 'earth'), playing = ref(false), speed = ref(1), labels = ref(true), time = ref(0), error = ref('')
const selected = computed(() => PLANETS.find(p => p.id === selectedId.value) || PLANETS[2])
const missionQuery = ref(''), missionPlanet = ref(''), era = ref('')
const viewMode = ref('perspective'), orbits = ref(true), following = ref(false), stage = ref(null)
const missions = computed(() => filterMissions({ query: missionQuery.value, planet: missionPlanet.value, era: era.value }))
const mission = computed(() => MISSIONS.find(item => item.id === route.query.mission) || null)
let scene, frame = 0, last = 0, seconds = 0, published = 0
function select(id) { if (!PLANETS.some(p => p.id === id)) return; selectedId.value = id; router.replace({ path: '/solar-system', query: { planet: id, ...(mission.value ? { mission: mission.value.id } : {}) } }) }
function selectMission(id) { if (id && !MISSIONS.some(m => m.id === id)) return; stop(); router.replace({ path: '/solar-system', query: { planet: selectedId.value, ...(id ? { mission: id } : {}) } }) }
function focusMissionTarget(id) { following.value = false; select(id); stop(); scene?.focus(id) }
watch(() => route.query.planet, id => { selectedId.value = PLANETS.some(p => p.id === id) ? id : 'earth'; scene?.selected(selectedId.value); if (following.value) scene?.follow(selectedId.value) })
watch(mission, item => scene?.highlight(item?.targets || []))
watch(labels, show => scene?.labels(show))
watch(orbits, show => scene?.orbits(show))
watch(viewMode, mode => { following.value = false; scene?.view(mode) })
function stop() { playing.value = false; cancelAnimationFrame(frame); last = 0; time.value = seconds }
function animate(now) { if (!playing.value) return; if (last) seconds = (seconds + Math.min(.05, (now - last) / 1000) * speed.value) % 600; last = now; scene?.update(seconds); if (now - published > 100) { time.value = seconds; published = now } frame = requestAnimationFrame(animate) }
function toggle() { if (playing.value) stop(); else if (scene && !error.value) { playing.value = true; last = 0; frame = requestAnimationFrame(animate) } }
function closeUp() { following.value = false; stop(); scene?.focus(selectedId.value) }
function followPlanet() { if (following.value) overview(); else { following.value = true; scene?.follow(selectedId.value) } }
function overview() { following.value = false; scene?.reset() }
function scrub(value) { stop(); seconds = sceneTime(value); time.value = seconds; scene?.update(seconds) }
function visibility() { if (document.hidden) stop() }
function contextLost(event) { event.preventDefault(); stop(); error.value = '图形上下文已丢失，请刷新页面恢复。行星文字图谱仍可阅读。' }
onMounted(() => { try { scene = createSolarScene(mount.value, select); scene.selected(selectedId.value); scene.highlight(mission.value?.targets || []); scene.canvas.addEventListener('webglcontextlost', contextLost) } catch (cause) { error.value = cause.message || '3D 图谱暂时无法加载，仍可选择行星阅读资料。' } document.addEventListener('visibilitychange', visibility) })
onUnmounted(() => { stop(); document.removeEventListener('visibilitychange', visibility); scene?.canvas.removeEventListener('webglcontextlost', contextLost); scene?.dispose() })
</script>
